public static void sortuj(int tab[]) {
    int n = tab.length;
    for (int i = 0; i < n; i++) {
        for (int j = 1; j < n - i; j++) {
            if (tab[j - 1] > tab[j]) {
                int tmp = tab[j - 1];
                tab[j - 1] = tab[j];
                tab[j] = tmp;
            }
        }
    }
}

